INSERT INTO books (title, description, language_code, isbn13, open_library_id, cover_url, published_year, publisher, page_count, sale_price_iqd, is_active) SELECT 'Rationalities, historicities', 'Critically revisiting Valery''s notion of a "crisis of spirit," this collection of Professor Janicaud''s essays orchestrates a meeting of the analytic and phenomenological traditions, ordinarily uninformed about each other, while passing along the way through such crucial contemporary landmarks as the crossroads of reason and power in the Habermas-Foucault debate, the place of a true philosophy of technology, and the destination of philosophy''s Hegelian and Heideggerian legacies.  These essays offer a preliminary reconnaissance of this terrain which philosophy must make its new and rightful home.', 'eng', '', 'OL1005550M', 'https://covers.openlibrary.org/b/olid/OL1005550M-L.jpg', 1997, 'Humanities Press', 175, 15000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM books WHERE open_library_id = 'OL1005550M');
