INSERT INTO books (title, description, language_code, isbn13, open_library_id, cover_url, published_year, publisher, page_count, sale_price_iqd, is_active) SELECT 'M. William Shak-Speare, His True Chronicle Historie of the Life and Death of King Lear and His Three Daughters', '"What modern readers and audiences generally know as ''Shakespeare''s King Lear'' is a composite construction created by merging The Tragedie of King Lear (1623) and the earlier (1608) Quarto version." "In the last twenty years these two texts have again been disentangled from one another, and recognised as different states in a process of textual production: but only since editors and critics have generally agreed that both texts were separately written by Shakespeare himself, who produced the 1623 version by adapting, editing and ''revising'' the Quarto." "This new critical edition presents the play in a largely unmodernised form, with a minimum of editorial interference; and argues that both in terms of its relation to the Folio and its character as an individual text, it is better approached formally and historically as an independent play than evaluated on the basis of a speculative theory of authorship."--BOOK JACKET.', 'eng', '9780133553635', 'OL10087305M', 'https://covers.openlibrary.org/b/olid/OL10087305M-L.jpg', 1995, 'Prentice Hall Trade', 176, 15000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM books WHERE open_library_id = 'OL10087305M') AND NOT EXISTS (SELECT 1 FROM books WHERE isbn13 = '9780133553635');
