INSERT INTO books (title, description, language_code, isbn13, open_library_id, cover_url, published_year, publisher, page_count, sale_price_iqd, is_active) SELECT 'The is-ought problem', 'Can OUGHT be derived from IS? This book presents a systematic investigation of this time-honored philosophical problem by means of modern alethic-deontic predicate logic. Two comprehensive introductory chapters into the philosophical and logical foundations make the text understandable also for non-logicians ethicists, social scientists and students of philosophy. New in this study are two leitmotifs: relevance and metalogical generality.  It turns out that is-ought inferences indeed exist, but they are all irrelevant in a precise logical sense. New proof techniques allow to establish this result for very broad classes of logics. A profound philosophical investigation of the question of analytical or strongly intersubjective is-ought bridge principles supplements the logical study. The final results imply incisive limitations for the justifiability of ethics as opposed to empirical science.', 'eng', '', 'OL1012394M', 'https://covers.openlibrary.org/b/olid/OL1012394M-L.jpg', 1997, 'Kluwer Academic', 332, 15000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM books WHERE open_library_id = 'OL1012394M');
